import { cookies, headers } from 'next/headers';

export default async function ThemeDisplay() {
  const cookieStore = await cookies();
  const headersList = await headers();

  const theme = cookieStore.get('theme')?.value || 'light';
  const acceptLanguage = headersList.get('accept-language') || 'en-US';

  const primaryLanguage = acceptLanguage.split(',')[0].split(';')[0].trim();

  return (
    <div className="theme-display">
      <h2>User Preferences</h2>
      <div className="preference-item">
        <strong>Theme:</strong> {theme}
      </div>
      <div className="preference-item">
        <strong>Preferred Language:</strong> {primaryLanguage}
      </div>
      <div className="preference-item">
        <strong>Full Accept-Language Header:</strong> {acceptLanguage}
      </div>
    </div>
  );
}

